#!/usr/bin/env node
// Build the page-scoped HtmlEmbed for an inline quiz on a Webflow landing page.
//
//   node scripts/build-embed.mjs --id lab-test-symptom-check \
//     --css webflow/lab-test-symptom-check.css --out webflow/
//
// Writes <id>.embed.html: the theme CSS in a <style> block, the engine bundle,
// and an explicit init scoped to [data-quiz="<id>"]. Paste it into ONE HtmlEmbed
// element placed after the quiz block (data_element_settings_tool > set_settings,
// key "code"). Page-level custom code rejects <script> on this site.
//
// The inline quiz is generated with "auto": false on purpose. The site footer
// loader injects the shared engine asset on every page that has a [data-quiz]
// root; that copy only auto-inits roots carrying data-quiz-auto, so leaving the
// attribute off keeps it from wiring a second set of handlers onto this quiz.
//
// Also writes fixtures/<id>.html, which loads the same embed so the E2E runs
// the exact code that ships.
//
// Requires a build first (`npm run build`).

import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (!arg.startsWith('--')) continue;
    const next = argv[i + 1];
    if (next && !next.startsWith('--')) {
      args[arg.slice(2)] = next;
      i += 1;
    } else args[arg.slice(2)] = true;
  }
  return args;
}

const args = parseArgs(process.argv.slice(2));
if (!args.id || !args.css || !args.out) {
  console.error('Usage: node scripts/build-embed.mjs --id <quiz-id> --css <file.css> --out <dir> [--fixture-wrap <file.html>]');
  process.exit(2);
}

const HTML_EMBED_LIMIT = 50000;

const css = (await readFile(args.css, 'utf8')).trim();
const engine = (await readFile('dist/maximus-quiz.iife.js', 'utf8'))
  .replace(/\n?\/\/# sourceMappingURL=.*$/m, '')
  .trim();
if (engine.includes('</script')) {
  console.error('error: engine bundle contains "</script", which would end the embed early.');
  process.exit(1);
}

const selector = `[data-quiz="${args.id}"]`;
const init = `(function(){var r=document.querySelector('${selector}');if(r&&!r.hasAttribute('data-quiz-init')){r.setAttribute('data-quiz-init','');window.MaximusQuiz.init({root:r});}})();`;
const embed = `<style>\n${css}\n</style>\n<script>\n${engine}\n${init}\n</script>\n`;

if (embed.length > HTML_EMBED_LIMIT) {
  console.error(`error: embed is ${embed.length} chars; Webflow's HtmlEmbed limit is ${HTML_EMBED_LIMIT}.`);
  process.exit(1);
}

const embedPath = join(args.out, `${args.id}.embed.html`);
await writeFile(embedPath, embed, 'utf8');
console.error(`wrote ${embedPath} (${embed.length} of ${HTML_EMBED_LIMIT} chars)`);

const block = (await readFile(join('build', `${args.id}.html`), 'utf8')).trim();
if (block.includes('data-quiz-auto')) {
  console.error('error: the generated block carries data-quiz-auto; set "auto": false in the definition.');
  process.exit(1);
}

const fixture = `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${args.id} (inline LP fixture)</title>
    <!-- Generated by scripts/build-embed.mjs. The quiz block and the embed are
         the exact artifacts inserted into Webflow. The card wrapper and design
         variables stand in for the landing page around them. -->
    <style>
      :root {
        --_maximus-ds---white: #fff; --_maximus-ds---gray-600: #6b7170; --_maximus-ds---gray-700: #4a4e4d;
        --_maximus-ds---gray-900: #1a1c1b; --_maximus-ds---warm-sand-100: #f5ede3; --_maximus-ds---warm-sand-200: #f0e0ce;
        --_maximus-ds---warm-sand-300: #e7c9ac; --_maximus-ds---persian-blue-300: #76a3db; --_maximus-ds---persian-blue-500: #0049bd;
        --_maximus-ds---persian-blue-800: #112f5b; --_maximus-ds---red-100: #ffc7c7; --_maximus-ds---green-200: #b0ebd0;
        --_maximus-ds---green-500: #52b784; --_maximus-ds---semantic--bg-brand: #0049bd; --_maximus-ds---semantic--fg-on-brand: #fff;
        --_typography---body: Arial, sans-serif; --_typography---heading: Georgia, serif; --_typography---mono: monospace;
      }
      body { margin: 0; background: #fff; font-family: var(--_typography---body); }
      .wl-plan_quiz { max-width: 720px; margin: 40px auto; padding: 40px; border-radius: 24px; background: var(--_maximus-ds---warm-sand-100); display: flex; flex-direction: column; gap: 20px; }
      .wl-plan_quiz-count { font-family: var(--_typography---mono); color: var(--_maximus-ds---gray-600); letter-spacing: .14em; text-transform: uppercase; font-size: 12px; }
      .lll-lf_text-link { color: var(--_maximus-ds---persian-blue-500); font-size: 15px; }
    </style>
  </head>
  <body>
    <div class="wl-plan_quiz">
      <div class="wl-plan_quiz-count">FIND OUT WHERE YOU STAND</div>
${block}
      <a href="https://app.maximustribe.com/labs-first" class="lll-lf_text-link">Already know treatment is right for you? See treatment options →</a>
    </div>
${embed}
  </body>
</html>
`;
const fixturePath = join('fixtures', `${args.id}.html`);
await writeFile(fixturePath, fixture, 'utf8');
console.error(`wrote ${fixturePath}`);
